const payload = msg.payload;

function reject(reason) {
    msg.statusCode = 400;
    msg.headers = { "Content-Type": "application/json" };
    msg.payload = { error: reason };
    return msg;
}

if (!payload || payload.schema_version !== "1.0" || !Array.isArray(payload.readings)) {
    return reject("Expected schema_version 1.0 and an array of readings");
}

if (payload.readings.length === 0) {
    return reject("At least one reading is required");
}

for (const reading of payload.readings) {
    if (!reading || typeof reading.device_id !== "string" || !reading.device_id.trim()) {
        return reject("Every reading requires a device_id");
    }
    if (typeof reading.timestamp !== "string" || Number.isNaN(Date.parse(reading.timestamp)) || !/(Z|[+-]\d{2}:\d{2})$/.test(reading.timestamp)) {
        return reject("Every reading requires a timezone-aware timestamp");
    }
    if (!["good", "uncertain", "bad"].includes(reading.quality)) {
        return reject("Invalid reading quality");
    }
    const values = reading.values;
    if (!values || typeof values !== "object" || Array.isArray(values) || Object.keys(values).length === 0) {
        return reject("Every reading requires measured values");
    }
    if (!Object.entries(values).every(([name, value]) => name && typeof value === "number" && Number.isFinite(value))) {
        return reject("Measurements must have names and finite numeric values");
    }
}

const latest = flow.get("latest") || {};
for (const reading of payload.readings) {
    latest[reading.device_id] = reading;
}
flow.set("latest", latest);

msg.statusCode = 202;
msg.headers = { "Content-Type": "application/json" };
msg.payload = { accepted: payload.readings.length };
return msg;

const latest = flow.get("latest") || {};
msg.statusCode = 200;
msg.headers = { "Content-Type": "application/json" };
msg.payload = {
    schema_version: "1.0",
    readings: Object.values(latest).sort((a, b) => a.device_id.localeCompare(b.device_id))
};
return msg;

msg.statusCode = 200;
msg.headers = { "Content-Type": "application/json" };
msg.payload = { status: "ok" };
return msg;
